mapper.select:
SELECT count(*)
FROM organization_access.tenant_membership_role_binding
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
  AND role_code = #{roleCode}

mapper.delete:
DELETE FROM organization_access.tenant_membership_role_binding
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
  AND role_code = #{roleCode}

mapper.update:
UPDATE organization_access.tenant_membership
SET permission_version = #{permissionVersion},
    version = #{version},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND membership_id = #{membershipId}
